export async function retry<T>(
  fn: (attempt: number) => Promise<T>,
  options: RetryOptions<T>
): Promise<T> {
  const {
    attempts,
    baseDelayMs,
    maxDelayMs = Infinity,
    factor = 2,
    jitter = "full",
    signal,
    sleep = defaultSleep,
    random = Math.random,
    isRetryable = () => true,
    onRetry,
  } = options;

  if (attempts < 1) throw new RangeError("attempts must be >= 1");
  if (baseDelayMs < 0) throw new RangeError("baseDelayMs must be >= 0");

  let lastError: unknown;
  for (let attempt = 1; attempt <= attempts; attempt++) {
    if (signal?.aborted) throw abortError(signal);
    try {
      return await fn(attempt);
    } catch (error) {
      lastError = error;
      if (attempt === attempts) break;
      if (signal?.aborted) throw abortError(signal);
      if (!isRetryable(error, attempt)) break;
      const raw = Math.min(baseDelayMs * factor ** (attempt - 1), maxDelayMs);
      const delayMs = jitter === "none" ? raw : jitter === "full" ? raw * random() : raw / 2 + raw * random() / 2;
      onRetry?.({ error, attempt, delayMs });
      await sleep(delayMs);
    }
  }
  throw new RetryError(`retry: failed after ${attempts} attempt(s)`, lastError, attempts);
}
